<?php

/**
 * @author Jacopo Viscuso, Emanuele Fornasier
 **/

namespace App\Html;

use DOMDocument;
use DOMElement;
use DOMXpath;

/**
 * Inserisce codice inline css prendendolo dal tag style di un documento
 **/
class CssInliner
{
    public static function inlineCss(string $htmlMail): string|false
    {

        libxml_use_internal_errors(true) and libxml_clear_errors();

        $thisDocument = new DOMDocument('1.0', 'UTF-8');     // istanzio la classe DOMDocument (serve per trasformare html in oggetto)
        $htmlMail = mb_convert_encoding($htmlMail, 'HTML-ENTITIES', "UTF-8");

        $internalErrors = libxml_use_internal_errors(true);

        $thisDocument->loadHTML($htmlMail);           // faccio il parsing dell'html mail

        libxml_use_internal_errors($internalErrors);

        $thisDocumentXPath = new DOMXpath($thisDocument);   // istanzio la classe DOMXpath (fa il parsing dei tag html)

        $styleTag = $thisDocumentXPath->query('//style');   // recupero il contenuto dei tag style
        $style = '';                                        // stringa con tutte le regole css contenute nei vari tag style
        if ($styleTag) :
            foreach ($styleTag as $s) :
                $style .= $s->nodeValue;
            endforeach;
        endif;
